MM.mnemo[10] = {"cards":[{"id":"ko-k3-0207","w":"내다","cs":"zaplatit; vydat; podat","en":"to pay (돈을 내다 = to pay money)","p":"v","o":"k","ex":"돈을 내기 전에","exc":"než zaplatíš; před zaplacením (을 → 4. pád; -기 전에 → předtím než)","h":"NE-DA ≈ NEDÁ: kdo nedá peníze, nezaplatí. 돈을 내다 = zaplatit.","m":"Příčinné sloveso k 나다 (vyjít ven, vzniknout): 내다 = „dát ven, vydat“. Nejčastější spojení: 돈을 내다 (zaplatit), 화를 내다 (rozzlobit se), 숙제를 내다 (odevzdat úkol).","tv":["내요"]},{"id":"ko-k3-0208","w":"들어오다","cs":"vejít; vstoupit (dovnitř)","en":"to come in","p":"v","o":"k","ex":"들어오기 전에 노크하세요.","exc":"Než vejdete, zaklepejte. (-기 전에 → předtím než)","h":"TŮ-RO ≈ DOOR (dveře) + 오다 = přijít: přijít dveřmi = vejít dovnitř.","m":"Složené z 들다 (vstoupit) + 오다 (přijít sem) = přijít dovnitř (směrem k mluvčímu). Opak 나가다 (vyjít ven) a 들어가다 (vejít směrem od mluvčího).","tv":["들어와요"]},{"id":"ko-k3-0209","w":"도망가다","cs":"utéct; uprchnout","en":"to run away","p":"v","o":"m","ex":"도망가기 전에 잡으세요.","exc":"Chyťte ho, než uteče. (-기 전에 → předtím než)","h":"TO-MANG ≈ TOMÁŠ S MANGEM: Tomáš ukradl mango a utíká.","m":"逃 prchnout + 亡 zmizet + 가다 jít = vzít nohy na ramena a zmizet, tedy utéct. Také 도망치다.","r":["do-逃","mang-亡"],"tv":["도망가요"]},{"id":"ko-k3-0210","w":"열다","cs":"otevřít","en":"to open","p":"v","o":"k","ex":"열기 전에","exc":"před otevřením; než otevřeš (-기 전에 → předtím než)","h":"JOL ≈ JOLANA: Jolana otevře dveře.","m":"Nepravidelné časování ㄹ: před ㄴ, ㅂ, ㅅ vypadává ㄹ (např. 여세요 = otevřete). Opak 닫다 (zavřít).","tv":["열어요"],"irr":"ㄹ (odpadá)"},{"id":"ko-k3-0211","w":"전에","cs":"před (časově); dříve","en":"before (+ noun)","p":"o","o":"m","ex":"3시 전에 만나요.","exc":"Sejdeme se před třetí hodinou.","h":"DŽON-E ≈ JOHNNY: Johnny tu byl dřív než ty. 먹기 전에 = před jídlem.","m":"前 před, dříve + částice 에 = před (něčím). Po podstatném jménu stojí samostatně (수업 전에), za slovesem ve tvaru -기 전에. Opak 후에 (po).","r":["jeon-前"]},{"id":"ko-k3-0212","w":"수업","cs":"vyučování; hodina (ve škole); lekce","en":"class","p":"n","o":"s","ex":"수업 전에","exc":"před vyučováním; před hodinou","h":"SU-OP ≈ SUP: v hodině za katedrou sedí sup a učí.","m":"授 předávat, vyučovat + 業 práce, obor = předávání znalostí, tedy vyučování nebo školní hodina. 業 jako v 직업 (povolání) nebo 졸업 (absolvování).","hada":1,"r":["su-授","eop-業"]},{"id":"ko-k3-0214","w":"시험","cs":"zkouška; test","en":"exam, test","p":"n","o":"s","ex":"시험 전에","exc":"před zkouškou; před testem","h":"ŠI-HOM ≈ ŠÍLENÝ HOROR: zkouška.","m":"試 zkoušet + 驗 ověřit = ověření znalostí, tedy zkouška nebo test. Časté spojení: 시험을 보다 = dělat zkoušku (doslova ‚vidět zkoušku‘).","r":["si-試","heom-驗"]},{"id":"ko-k3-0215","w":"여름 휴가","cs":"letní prázdniny; letní dovolená","en":"summer vacation","p":"f","o":"m","ex":"여름 휴가 전에","exc":"před letními prázdninami; před letní dovolenou","h":"여름 = léto („JO, RUM!“) + 휴가 = dovolená (HJU-GA ≈ HUGO jede k moři).","m":"Složené z 여름 (léto) + 휴가 (volno, dovolená: 休 odpočinek + 暇 volný čas).","r":["hyu-休","ga-暇"]},{"id":"ko-k3-0216","w":"숙제하다","cs":"dělat domácí úkoly","en":"to do homework","p":"v","o":"s","ex":"친구들하고 놀기 전에 숙제할 거예요.","exc":"Než půjdu ven s kamarády, udělám si domácí úkol. (들 → množné číslo; 하고 → s; -기 전에 → předtím než)","h":"숙제 (úkol tvrdý jako SUK) + 하다 = dělat úkoly.","m":"宿 přenocovat, doma + 題 úkol, otázka + 하다 dělat = dělat úkol na doma. 題 jako v 문제 (otázka, problém).","r":["suk-宿","je-題"]},{"id":"ko-k3-0217","w":"노크하다","cs":"zaklepat; klepat (na dveře)","en":"to knock","p":"v","o":"e","ex":"들어오기 전에 노크하세요.","exc":"Než vejdete, zaklepejte. (-기 전에 → předtím než)","h":"Z angličtiny knock = zaklepat.","m":"Z anglického knock (zaklepat) + 하다 (dělat). Klepání na dveře se korejsky řekne 문을 노크하다 nebo 똑똑 두드리다."},{"id":"ko-k3-0218","w":"잡다","cs":"chytit; uchopit; držet","en":"to catch","p":"v","o":"k","ex":"도망가기 전에 잡으세요.","exc":"Chyťte ho, než uteče. (-기 전에 → předtím než)","h":"ČAP ≈ ČAPNOUT: čapni ho!","m":"Výslovnost [잡따]. Má široké použití: chytit míč (공을 잡다), chytit taxík (택시를 잡다) nebo domluvit termín (약속을 잡다).","tv":["잡아요","잡았어요","잡을 거예요"]},{"id":"ko-k3-0219","w":"생각하다","cs":"myslet; přemýšlet","en":"to think","p":"v","o":"k","ex":"사기 전에 잘 생각하세요.","exc":"Než to koupíte, dobře si to rozmyslete. (-기 전에 → předtím než)","h":"SENG-GAK ≈ SEN: přemýšlíš, jako bys snil.","m":"Základ 생각 (myšlenka, nápad) + 하다 (dělat). Časté spojení: 좋은 생각이에요! = To je dobrý nápad!"},{"id":"ko-k3-0220","w":"정말요?","cs":"Opravdu?; Vážně?","en":"Really?","p":"f","o":"m","ex":"정말요? 몰랐어요.","exc":"Opravdu? To jsem nevěděl.","h":"정말 (DŽONG-MAL ≈ DŽONKA MALÁ) + 요: „Vážně? Opravdu?“","m":"正 správný, pravý + 말 slovo + zdvořilostní 요 = ‚Opravdu? / Vážně?‘. Neformálně bez 요: 정말? nebo 진짜?.","r":["jeong-正"]}],"gram":{"id":"ko-k3-g10","w":"-기 전에","en":"Before -ing","cs":"před (něčím); než…, dříve než…","vy":"Vzorec -기 전에 vyjadřuje, že se něco stane dříve než jiný děj nebo časový údaj. U sloves se ke kmeni připojí koncovka -기 (tím vznikne podstatné jméno slovesné) a za ni slovo 전에 (‚před‘). U běžných podstatných jmen nebo časových údajů (např. 수업, 1시) stojí 전에 samostatně bez -기.","m":"Podstatné jméno 전 (前) znamená ‚předek, dříve‘ a částice 에 určuje čas — dohromady 전에 = ‚před‘. Opakem je -ㄴ/은 후에 nebo -ㄴ/은 다음에 (poté, co / po).","s":[["수업 전에","před hodinou / před vyučováním"],["일요일 전에","před nedělí"],["1시 전에","před jednou hodinou"],["집에 가기 전에","než půjdu domů / před odchodem domů"],["공부하기 전에","než se začnu učit / před učením"],["돈을 내기 전에","než zaplatíš / před zaplacením"],["여기 오기 전에 뭐 했어요?","Co jsi dělal, než jsi sem přišel?"],["친구들하고 놀기 전에 숙제할 거예요.","Než půjdu ven s kamarády, udělám si domácí úkol."],["들어오기 전에 노크하세요.","Než vejdete, zaklepejte."],["사기 전에 잘 생각하세요.","Než to koupíš, dobře si to rozmysli."],["도망가기 전에 잡으세요.","Chyťte ho, než uteče!"],["밥 먹기 전에 운동하는 것이 더 좋아요.","Je lepší si zacvičit před jídlem."],["정말요? 몰랐어요.","Vážně? To jsem nevěděl."],["여섯 시 전에","před šestou hodinou"],["3시 전에 만나요.","Sejdeme se před třetí."],["제가 오늘 자기 전에 전화할게요.","Zavolám dneska večer, než půjdu spát."]]}};
